using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 bool CancelRetryFutureCase=>FlowCase=="dircancelretry-future";
 bool CancelRetryChoiceCase=>FlowCase=="dircancelretry-choice";
 TroopDispatch CancelRetryOriginal()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.First();
 TroopReceipt CancelRetryInitial()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single(r=>r.Id==CancelRetryOriginal().Id);
 TroopDispatch CancelRetryCopy()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last(d=>d.Message==CancelRetryOriginal().Message);
 TroopReceipt CancelRetryReceipt()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single(r=>r.Id==CancelRetryCopy().Id);
 long CancelRetryRequested()=>game!.Session.DiagnosticSnapshot().NewMilitary!.Requests.Single(q=>q.Input.Id==CancelRetryOriginal().Id).Input.DirectiveCancellation!.EffectiveAt;
 void OneCancelOriginalEffect(){var w=game!.Session.DiagnosticSnapshot();var x=w.NewMilitary!.UnitDirective!.Cancellation!;Check(!CancelRetryInitial().Delivered,"original cancellation loss is immutable");Check(w.Messaging.Receipts.Count(r=>r.MessageId==CancelRetryOriginal().Message)==1,"one formal receipt of original cancellation envelope");Check(x.Effects.Length==1&&x.Effects.Single().Id==CancelRetryOriginal().Id,"copied cancellation has one canonical root effect");Check(!NewGameMilitary.HeldPapers(w,w.ElapsedSeconds).Any(h=>h.Message==CancelRetryOriginal().Message),"unretained cancellation never gains a fictional physical original");}
 async Task DirectiveCancelRetryStep(int n){await Frame();var s=game!.Session;
  if(n==0){game.SelectKnownMilitary(NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[1]);game.ChooseMilitary(NewMilitaryAction.RemoteRecall);game.Advance(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);game.Press("unit-directive-hold");if(CancelRetryFutureCase)game.ExerciseDirectiveCancelAt(s.Seconds+180);else game.Press("unit-directive-cancel");if(CancelRetryChoiceCase){game.ExerciseDirectiveCancelAt(s.Seconds+180);Check(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Length==2,"two independently issued cancellation originals exist");}Check(!game.ButtonEnabled("unit-directive-cancel-retry"),"failure is not invented at dispatch");}
  if(n==1){game.Advance(CancelRetryOriginal().DueAt);Check(!CancelRetryInitial().Delivered&&!game.ButtonEnabled("unit-directive-cancel-retry"),"actual missed cancellation cannot be retried before its physical report");}
  if(n==2){game.Advance(CancelRetryInitial().ReplyDueAt);game.Advance(Math.Max(s.Seconds,ArmyEnd()+2));game.SelectCancellationOriginal(CancelRetryOriginal().Id);Check(game.SelectedCancellationOriginalId==CancelRetryOriginal().Id.Value&&game.ButtonEnabled("unit-directive-cancel-retry"),"specific owned cancellation and known failure enable explicit retry");}
  if(n==3){var before=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==CancelRetryOriginal().Message);game.Press("unit-directive-cancel-retry");Check(CancelRetryCopy().Id!=CancelRetryOriginal().Id&&CancelRetryCopy().Message==before.Id&&s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==before.Id)==before,"physical copy preserves cancellation target requested time recipient and deadline");Check(!game.ButtonEnabled("unit-directive-cancel-retry")&&NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),CancelRetryOriginal().Id).Contains("取消を再送"),"own dispatched copy is shown without leaking remote result");}
  if(n==4){game.Advance(CancelRetryCopy().DueAt);Check(CancelRetryReceipt().Delivered,"copy actually reaches same unit at its known fixed post");Check(!NewGameMilitary.ReceiptConfirmedToSender(s.DiagnosticSnapshot(),CancelRetryOriginal().Message,s.PlayerControl.Value),"distant formal receipt is not sender knowledge");if(CancelRetryFutureCase)Check(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects.Length==0,"copy does not accelerate requested future effective time");else OneCancelOriginalEffect();Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),CancelRetryOriginal().Id).Contains("取消を再送"),"unknown receipt does not change visible status");}
  if(n==5){game.Advance(CancelRetryReceipt().ReplyDueAt);Check(NewGameMilitary.ReceiptConfirmedToSender(s.DiagnosticSnapshot(),CancelRetryOriginal().Message,s.PlayerControl.Value),"physical copy reply confirms original cancellation receipt");Check(!game.ButtonEnabled("unit-directive-cancel-retry"),"known receipt prevents another duplicate copy");if(CancelRetryFutureCase)Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),CancelRetryOriginal().Id).Contains("効力時刻を待つ"),"known receipt truthfully waits for future effect");else Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),CancelRetryOriginal().Id).Contains("未実行の対象原本を取消"),"received copy reply shows selected root result");}
  if(n==6){if(CancelRetryFutureCase){game.Advance(CancelRetryRequested());OneCancelOriginalEffect();Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),CancelRetryOriginal().Id).Contains("効力時刻を待つ"),"future effect remains unknown until its actual notice arrives");}else{game.Advance(s.Seconds+3);OneCancelOriginalEffect();}if(CancelRetryChoiceCase)Check(game.SelectedCancellationOriginalId==CancelRetryOriginal().Id.Value&&s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects.All(e=>e.Id==CancelRetryOriginal().Id),"older selected cancellation is not confused with later unreceived one");}
  if(n==7){if(CancelRetryFutureCase){var notice=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Notices.Single();game.Advance(notice.DueAt);Check(NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),CancelRetryOriginal().Id).Contains("未実行の対象原本を取消"),"future physical result reaches sender");}else{game.Advance(s.Seconds+3);game.Press("rotate");}OneCancelOriginalEffect();}
  game.Refresh();Check(game.RecognitionModelsMatch(),"actual cancellation retry 3D matches known world at"+n);game.Press("save");await WaitSave();
 }
 async Task BeginDirectiveCancelRetryContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<=4;n++)await RecognitionStep(n);for(int n=0;n<8;n++){await DirectiveCancelRetryStep(n);game!.SaveCheckpoint("cancelretry"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreDirectiveCancelRetry(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,row=>row.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<8;n++){game!.LoadCheckpoint("cancelretry"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"same cancellation original selection status world and3D after restore"+n);await Capture("restored-s"+n,true);for(int k=n+1;k<8;k++)await DirectiveCancelRetryStep(k);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same cancellation retry future from"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_DIRECTIVE_CANCEL_RETRY_RESTORED "+n);}}
 async Task RunDirectiveCancelRetryChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreDirectiveCancelRetry();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-directive-cancel-retry-film")){game!.LoadCheckpoint("cancelretry4");game.Press("auto");string dir=Path.Combine(TestOutput,"film",TestKey??"normal");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"cancel-retry-"+n.ToString("D3")+".png"));}game.Press("pause");File.WriteAllText(Path.Combine(TestOutput,"film-manifest.json"),System.Text.Json.JsonSerializer.Serialize(new{Directory=Path.GetRelativePath(TestOutput,dir),Frames=180,Checkpoint=4,Action="physical-copy-reply-courier-returns"}));}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_DIRECTIVE_CANCEL_RETRY_PASSED "+FlowCase);}
}
